__global__ void reduction_kernel_phase2(float* partial_results, float* final_result,
                                         int num_blocks) {
    extern __shared__ float sdata[];

    unsigned int tid = threadIdx.x;

    // 加载部分结果
    float sum = 0.0f;
    for (unsigned int i = tid; i < num_blocks; i += blockDim.x) {
        sum += partial_results[i];
    }
    sdata[tid] = sum;
    __syncthreads();

    // 归约
    for (unsigned int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sdata[tid] += sdata[tid + stride];
        }
        __syncthreads();
    }

    // 写入最终结果
    if (tid == 0) {
        *final_result = sdata[0];
    }
}
```

