float reduce(float* d_input, int length) {
    int block_size = 256;
    int chunk_size = 4096;  // 每个块处理的数据量

    // 计算需要的块数量
    int num_blocks = (length + chunk_size - 1) / chunk_size;

    // 分配部分结果数组
    float* d_partial_results;
    cudaMalloc(&d_partial_results, num_blocks * sizeof(float));

    // 阶段1：并行归约各个块
    int shared_mem_size = block_size * sizeof(float);
    reduction_kernel_phase1<<<num_blocks, block_size, shared_mem_size>>>(
        d_input, d_partial_results, length, chunk_size);

    // 阶段2：归约部分结果
    reduction_kernel_phase2<<<1, block_size, shared_mem_size>>>(
        d_partial_results, d_final_result, num_blocks);

    // 复制结果回主机
    float result;
    cudaMemcpy(&result, d_final_result, sizeof(float), cudaMemcpyDeviceToHost);

    cudaFree(d_partial_results);
    return result;
}
