## 10.12 代码示例完整实现

### 10.12.1 完整的归约库

```cuda
// reduction_library.cuh
#ifndef REDUCTION_LIBRARY_CUH
#define REDUCTION_LIBRARY_CUH

#include <cuda_runtime.h>

// 归约类型枚举
enum class ReductionType {
    SUM,
    MAX,
    MIN,
    PRODUCT
};

// 归约操作符模板
template <ReductionType TYPE>
struct ReductionOperator;

template <>
struct ReductionOperator<ReductionType::SUM> {
    __device__ static float identity() { return 0.0f; }
    __device__ static float apply(float a, float b) { return a + b; }
};

template <>
struct ReductionOperator<ReductionType::MAX> {
    __device__ static float identity() { return -INFINITY; }
    __device__ static float apply(float a, float b) { return fmaxf(a, b); }
};

template <>
struct ReductionOperator<ReductionType::MIN> {
    __device__ static float identity() { return INFINITY; }
    __device__ static float apply(float a, float b) { return fminf(a, b); }
};

template <>
struct ReductionOperator<ReductionType::PRODUCT> {
    __device__ static float identity() { return 1.0f; }
    __device__ static float apply(float a, float b) { return a * b; }
};

// 通用归约内核
template <ReductionType TYPE, unsigned int BLOCK_SIZE, unsigned int COARSE_FACTOR>
__global__ void reduction_kernel_generic(float* input, float* output, int length) {
    __shared__ float sdata[BLOCK_SIZE];

    unsigned int tid = threadIdx.x;
    unsigned int i = blockIdx.x * BLOCK_SIZE * COARSE_FACTOR + threadIdx.x;

    // 使用运算符模板
    using Op = ReductionOperator<TYPE>;
    float result = Op::identity();

    // 粗化处理
    #pragma unroll
    for (unsigned int j = 0; j < COARSE_FACTOR; j++) {
        unsigned int idx = i + j * BLOCK_SIZE;
        if (idx < length) {
            result = Op::apply(result, input[idx]);
        }
    }

    sdata[tid] = result;
    __syncthreads();

    // 展开的归约
    if (BLOCK_SIZE >= 512) {
        if (tid < 256) sdata[tid] = Op::apply(sdata[tid], sdata[tid + 256]);
        __syncthreads();
    }

    if (BLOCK_SIZE >= 256) {
        if (tid < 128) sdata[tid] = Op::apply(sdata[tid], sdata[tid + 128]);
        __syncthreads();
    }

    if (BLOCK_SIZE >= 128) {
        if (tid < 64) sdata[tid] = Op::apply(sdata[tid], sdata[tid + 64]);
        __syncthreads();
    }

    // 最后的warp归约
    if (tid < 32) {
        volatile float* vsdata = sdata;
        if (BLOCK_SIZE >= 64) vsdata[tid] = Op::apply(vsdata[tid], vsdata[tid + 32]);
        if (BLOCK_SIZE >= 32) vsdata[tid] = Op::apply(vsdata[tid], vsdata[tid + 16]);
        if (BLOCK_SIZE >= 16) vsdata[tid] = Op::apply(vsdata[tid], vsdata[tid + 8]);
        if (BLOCK_SIZE >= 8)  vsdata[tid] = Op::apply(vsdata[tid], vsdata[tid + 4]);
        if (BLOCK_SIZE >= 4)  vsdata[tid] = Op::apply(vsdata[tid], vsdata[tid + 2]);
        if (BLOCK_SIZE >= 2)  vsdata[tid] = Op::apply(vsdata[tid], vsdata[tid + 1]);
    }

    if (tid == 0) {
        output[blockIdx.x] = sdata[0];
    }
}

// 主机端接口
class ReductionLibrary {
public:
    static float reduce(float* d_input, int length, ReductionType type);

private:
    static const int BLOCK_SIZE = 256;
    static const int COARSE_FACTOR = 4;
};

#endif // REDUCTION_LIBRARY_CUH
```

